```sql
/* Процент наборов с японским переводом, которые доступны только в non-foil */
SELECT
    /* Доля наборов с isforeignonly/nonfoil среди наборов с японским переводом */
    SUM(CASE WHEN s."isnonfoilonly" = 1 THEN 1 ELSE 0 END) * 100.0
    / NULLIF(COUNT(DISTINCT st."setcode"), 0) AS percentage
FROM set_translations st
JOIN sets s ON s."code" = st."setcode"
WHERE st."language" = 'Japanese';
```

```sql
/* Процент карт без силы (power IS NULL или '*'), которые имеют французский язык */
SELECT
    /* Вычисляем процент: французские карты без силы / все карты без силы * 100 */
    (COUNT(CASE WHEN fd."language" = 'French' THEN 1 END)::numeric
     / NULLIF(COUNT(*), 0)::numeric) * 100 AS percentage
FROM foreign_data fd
WHERE fd."power" IS NULL OR fd."power" = '*';
```

```sql
/* Доля карт с французским языком среди карт Story Spotlight */
SELECT
    /* Процент: французские Story Spotlight / все Story Spotlight * 100 */
    (COUNT(DISTINCT c.id) FILTER (WHERE fd."language" = 'French')::numeric
     / NULLIF(COUNT(DISTINCT c.id), 0)) * 100 AS percentage
FROM cards c
JOIN foreign_data fd ON fd."uuid" = c."uuid"
WHERE c."isstoryspotlight" = 1;
