```sql
/* Процент героев Marvel Comics среди супергероев с ростом от 150 до 180 см */
SELECT
    /* Расчёт процента: доля героев Marvel Comics * 100 */
    (SUM(CASE WHEN p."publisher_name" = 'Marvel Comics' THEN 1 ELSE 0 END)::numeric
     / COUNT(p."id")::numeric) * 100 AS marvel_percentage
FROM "superhero" s
JOIN "publisher" p ON s."publisher_id" = p."id"
WHERE s."height_cm" BETWEEN 150 AND 180;
```

```sql
/* Calculate the percentage of superheroes with 'Bad' alignment and how many of them were published by Marvel Comics */
SELECT
    /* Percentage of 'Bad' aligned superheroes among all superheroes */
    (COUNT(CASE WHEN a."alignment" = 'Bad' THEN 1 END)::numeric / COUNT(s."id")) * 100 AS bad_alignment_percentage,
    /* Count of 'Bad' aligned superheroes published by Marvel Comics */
    COUNT(CASE WHEN a."alignment" = 'Bad' AND p."publisher_name" = 'Marvel Comics' THEN 1 END) AS bad_alignment_marvel_count
FROM "superhero" s
LEFT JOIN "alignment" a ON s."alignment_id" = a."id"
LEFT JOIN "publisher" p ON s."publisher_id" = p."id";
```

