```sql
/* Находим студента с максимальным доходом и выводим его полное имя и источник дохода */
SELECT
    m."first_name" || ' ' || m."last_name" AS "full_name",
    i."source" AS "income_source"
FROM "income" i
JOIN "member" m ON m."member_id" = i."link_to_member"
WHERE i."amount" = (
    /* Максимальная сумма дохода среди всех записей */
    SELECT MAX("amount") FROM "income"
);
```

```sql
/* Соотношение клиентов с валютой EUR к клиентам с валютой CZK */
SELECT
    /* Количество клиентов с EUR */
    COUNT(*) FILTER (WHERE "currency" = 'EUR')::numeric
    /
    /* Количество клиентов с CZK (защита от деления на ноль) */
    NULLIF(COUNT(*) FILTER (WHERE "currency" = 'CZK'), 0) AS ratio
FROM "customers";
```

```sql
/* Count "discount" gas stations in Czech Republic (CZE) and Slovakia (SVK), then compute the difference */
SELECT
    /* Difference: CZE discount stations minus SVK discount stations */
    SUM(CASE WHEN "country" = 'CZE' THEN 1 ELSE 0 END)
    - SUM(CASE WHEN "country" = 'SVK' THEN 1 ELSE 0 END) AS "difference"
FROM "gasstations" g
WHERE LOWER(g."segment") = 'discount'
  AND g."country" IN ('CZE', 'SVK');
```

